ct_scalar(observations, ''$.observations.payeeVPA.account.customer.attribs.city'') AS \\"City\\", json_extract_scalar(observations, ''$.observations.payeeVPA.account.customer.attribs.gstn'') AS \\"GSTN\\", json_extract_scalar(observations, ''$.observations.payeeVPA.account.customer.attribs.state'') AS \\"State\\", json_extract_scalar(observations, ''$.observations.payeeVPA.account.customer.attribs.status'') AS \\"Status\\", json_extract_scalar(observations, ''$.observations.payeeVPA.account.customer.attribs.channel'') AS \\"Channel\\", json_extract_scalar(observations, ''$.observations.payeeVPA.account.customer.email'') AS \\"emailId\\", json_extract_scalar(observations, ''$.observations.payeeVPA.account.customer.attribs.pincode'') AS \\"PinCode\\", json_extract_scalar(observations, ''$.observations.payeeVPA.account.customer.attribs.district'') AS \\"District\\", json_extract_scalar(observations, ''$.observations.payeeVPA.account.customer.attribs.latitude'') AS \\"Latitude\\", json_extract_scalar(observations, ''$.observations.payeeVPA.account.customer.attribs.longitude'') AS \\"Longitude\\", json_extract_scalar(observations, ''$.observations.payeeVPA.account.customer.attribs.updatedBy'') AS \\"Updated By\\", json_extract_scalar(observations, ''$.observations.payeeVPA.account.customer.attribs.createdDate'') AS \\"Created By\\", json_extract_scalar(observations, ''$.observations.payeeVPA.attribs.AddressLine1'') AS \\"addressLine1\\", json_extract_scalar(observations, ''$.observations.payeeVPA.attribs.AddressLine2'') AS \\"addressLine2\\", json_extract_scalar(observations, ''$.observations.payeeVPA.account.customer.verifiedName'') AS \\"Business Name\\", json_extract_scalar(observations, ''$.observations.payeeVPA.account.customer.attribs.merchantType'') AS \\"Merchant Type\\", json_extract_scalar(observations, ''$.observations.payeeVPA.account.customer.registered_mobile'') AS \\"Mobile Number\\", json_extract_scalar(observations, ''$.observations.payeeVPA.account.customer.attribs.turnoverType'') AS \\"Turnover Type\\" FROM t8refined.analytics.trans l where l.vcuniquetransid = :VpaAddress  and  dttrxntime  between :StartDate and :EndDate and itenantid = :tenantid  order by dttrxntime desc limit 50000"     
    }
} '::text, false::boolean, true::boolean, false::boolean, '510'::integer, '12'::integer, '3'::integer)
